<?php require 'includes/layout.php';require_login();$s=db()->prepare('SELECT game,score,created_at FROM scores WHERE user_id=? ORDER BY created_at DESC LIMIT 50');$s->execute([user()['id']]);$rows=$s->fetchAll();top('Game History');?><div class="panel"><table><thead><tr><th>Game</th><th>Score</th><th>Played</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e(ucfirst($r['game']))?></td><td><?=e($r['score'])?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?></tbody></table><?php if(!$rows):?><p>Nothing played yet!</p><?php endif;?></div><?php bottom(); ?>